const crypto = require('crypto');
const input = $input.first().json;
const body = input.body || input;

if (!body.email || !body.company_name) {
  return [{ json: { error: true, message: 'Email and company_name required' } }];
}

const clientCode = body.company_name.toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 20) + '_' + Date.now().toString(36).slice(-4);
const apiKey = 'gv_' + crypto.randomBytes(32).toString('hex');
const webhookSecret = crypto.randomBytes(24).toString('base64url');

return [{ json: {
  email: body.email,
  company_name: body.company_name,
  contact_name: body.name || body.contact_name || '',
  domain: body.domain || '',
  plan_type: body.plan || 'standard',
  client_code: clientCode,
  api_key: apiKey,
  webhook_secret: webhookSecret,
  onboarding_steps: [
    { step: 1, name: 'account_created', status: 'completed' },
    { step: 2, name: 'domain_configured', status: 'pending' },
    { step: 3, name: 'first_contact_added', status: 'pending' },
    { step: 4, name: 'first_keyword_added', status: 'pending' },
    { step: 5, name: 'notification_setup', status: 'pending' },
    { step: 6, name: 'first_campaign_created', status: 'pending' }
  ]
}}];

const input = $input.first().json;
const body = input.body || input;
return [{ json: { client_code: body.client_code, step_name: body.step, step_data: body.data || {} } }];
